58:- `GET /api/heads` returns `{ heads: [{ id, name, createdAt, bytes, url, xrUrl }], uploadsEnabled }`. `?q=` filters names. `url` downloads the GLB; `xrUrl` opens that scan with live voice and the person's name.
59:- `POST /api/heads?name=<display name>` accepts a self-contained GLB v2 body, at most 50 MiB, with `Content-Type: model/gltf-binary` and `Authorization: Bearer <HEAD_LIBRARY_TOKEN>`. Returns the new head with status 201. Each upload gets a unique id; existing scans are never overwritten. Without the token configured, uploads return 503; reads still work.
60-- SQLite metadata lives in `head/builds/.library.sqlite`; GLBs remain in individual build folders. Back up the whole builds folder together. Neither files nor catalog belong in git. Uploaded scans are accessible to anyone with the app link, like the existing head files.
61-
62-## Secrets
63-All in .env, never committed. Code must start without them and say which feature is off.
          input.type = type;
          input.placeholder = "(not said: typical)";
          input.value = heard ?? "";
        }
        input.dataset.path = path;
        row.appendChild(input);
        $("fields").appendChild(row);
      }
      const nm = document.createElement("label");
      nm.textContent = "Name ";
      nm.innerHTML += `<input data-path="name" value="${(r.heard.name || $("voiceName").value).replace(/"/g, "")}">`;
      $("fields").prepend(nm);
      $("confirm").hidden = false;
      if (r.rejected?.length) $("confirmStatus").textContent = "We couldn't make sense of: " + r.rejected.join(", ") + ". Please check them.";
    }
    $("confirmBtn").onclick = async () => {
      const profile = {};
      let name = "";
      for (const el of document.querySelectorAll("#fields [data-path]")) {
        const path = el.dataset.path;
        let v = el.value.trim();
        if (path === "name") { name = v; continue; }
        if (v === "") v = null;
        else if (el.tagName === "SELECT" && path === "habits.smoker") v = v === "yes";
        else if (el.type === "number") v = Number(v);
        setPath(profile, path, v);
      }
      const res = await fetch("/api/interview/confirm", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ name, profile, speech: $("transcript").textContent }) });
      const j = await res.json().catch(() => ({}));
      $("confirmStatus").textContent = res.ok ? "Saved. Thanks! Now press \"Meet your future self\" below." : "Not saved: " + (j.error || res.status);
    };

    $("askForm").onsubmit = (e) => {
      e.preventDefault();
      const q = $("question").value.trim();
      if (!q) return;
      ctx = ctx || new AudioContext(); // created on a click, so the browser allows sound
      ctx.resume();
      const p = document.createElement("p");
      p.textContent = "You: " + q;
      $("chat").appendChild(p);
      $("question").value = "";
      gotFirst = false;
      askedAt = performance.now();
      const ws = ensureSocket();
      const msg = JSON.stringify({ type: "text", question: q });
      if (ws.readyState === 1) ws.send(msg); else ws.addEventListener("open", () => ws.send(msg), { once: true });
    };

    $("raw").onclick = () => play(true);
    $("aged").onclick = () => play(false);
  </script>
</body>
</html>
