const qs = ["Did we ever manage to buy a house?","Was I okay with money?","How is my health?","Do you have any regrets?","What should I change right now?","Are you proud of me?","Will I have enough to retire?","Any advice for me?"];
const ask = (q) => new Promise((resolve) => {
  const ws = new WebSocket("wss://uncle.health/voice"); const out = []; let src = null; let started = false;
  const t = setTimeout(() => { ws.close(); resolve({ q, out, src, timeout: true }); }, 15000);
  ws.onmessage = (e) => { const m = JSON.parse(e.data);
    if (m.type === "reply" && m.sentence) { out.push(m.sentence); if (m.timing) src = m.timing.source + " " + m.timing.thinkMs + "ms"; }
    if (m.type === "reply" && m.done && started) { clearTimeout(t); ws.close(); resolve({ q, out, src }); }
    if (m.type === "status" && m.state === "listening" && !started && out.length) {} };
  ws.onopen = () => { ws.send(JSON.stringify({ type: "start", name: "Probe", sex: "female", apparent_age: 70 })); setTimeout(() => { out.length = 0; started = true; ws.send(JSON.stringify({ type: "text", question: q })); }, 4000); };
});
for (const q of qs) { const r = await ask(q); console.log(`\nQ: ${q}\n[${r.src}]${r.timeout ? " TIMEOUT" : ""}\n` + r.out.map((s) => "  - " + s).join("\n")); }
EOF
node $TMPDIR/probe.mjs 2>&1 | head -80

