      setPath(profile, el.dataset.path, v);
    }
    savedSex = profile.sex || "";
    $("confirm").disabled = true;
    const res = await fetch("/api/interview/confirm", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ name, profile, speech: $("transcript").textContent }) }).catch(() => null);
    const j = res ? await res.json().catch(() => ({})) : {};
    $("confirm").disabled = false;
    if (!res || !res.ok) return say("e-confirm", "We couldn't save your answers: " + (j.error || (res ? res.status : "no connection")) + ". Try again.");
    finish();
  };

  // ---- hand over to the headset ----
  let savedSex = "";
  async function finish() {
    const params = new URLSearchParams({ voice: "live", name });
    if (savedSex) params.set("sex", savedSex); // the headset page defaults to male otherwise
    let headNote = "No head scan is saved under this name yet, so the headset shows a stand-in face. The voice and numbers are still yours.";
    let scanned = null;
    if (job) {
      show("s-done");
      say("head-note", "Your head is still building. Hold on.");
      $("open-xr").setAttribute("aria-disabled", "true");
      const r = await waitForHead((stage) => say("head-note", "Building your head: " + stage));
      scanned = r.head || null;
      if (r.failed) headNote = "Your head could not be built (" + r.failed + "), so the headset shows a stand-in face. Your voice and numbers are still yours.";
      $("open-xr").removeAttribute("aria-disabled");
    }
    if (scanned) { params.set("head", scanned.id); headNote = "Your new head scan will appear across the table."; }
    else try {
      const { heads } = await (await fetch("/api/heads?q=" + encodeURIComponent(name))).json();
      const match = (heads || []).find((h) => h.name.toLowerCase() === name.toLowerCase());
      if (match) { params.set("head", match.id); headNote = "Your saved head scan will appear across the table."; }
    } catch { /* the library is optional */ }
    $("open-xr").href = "/xr/?" + params;
    $("open-laptop").href = "/?name=" + encodeURIComponent(name);
    say("head-note", headNote + (voiceOk ? "" : " " + voiceProblem));
    show("s-done");
  }
</script>

