const { chromium } = require("playwright");
const b = await chromium.launch({ executablePath: "/Users/jeffreywongbusiness/Library/Caches/ms-playwright/chromium_headless_shell-1248/chrome-headless-shell-mac-arm64/chrome-headless-shell", args: ["--use-gl=swiftshader", "--enable-unsafe-swiftshader"] });
const pg = await b.newPage({ viewport: { width: 1280, height: 800 } });
await pg.goto("http://localhost:3001/xr/?head=isaac");
await pg.waitForFunction(() => window.uncle?.head, null, { timeout: 20000 });
await pg.waitForTimeout(1500);
const r = await pg.evaluate(() => {
  const o = window.uncle.head.object;
  o.updateWorldMatrix(true, true);
  const mn = [1e9, 1e9, 1e9], mx = [-1e9, -1e9, -1e9];
  const names = [];
  o.traverse((m) => {
    if (!m.isMesh && !m.isSkinnedMesh) return;
    names.push(m.name + ":" + (m.material?.type));
    const g = m.geometry; g.computeBoundingBox();
    const bb = g.boundingBox;
    for (const x of [bb.min.x, bb.max.x]) for (const y of [bb.min.y, bb.max.y]) for (const z of [bb.min.z, bb.max.z]) {
      const e = m.matrixWorld.elements;
      const w = [e[0] * x + e[4] * y + e[8] * z + e[12], e[1] * x + e[5] * y + e[9] * z + e[13], e[2] * x + e[6] * y + e[10] * z + e[14]];
      for (let i = 0; i < 3; i++) { mn[i] = Math.min(mn[i], w[i]); mx[i] = Math.max(mx[i], w[i]); }
    }
  });
  return { min: mn.map((v) => +v.toFixed(3)), max: mx.map((v) => +v.toFixed(3)), names, mirrorPos: window.uncle.head.object.parent.position.toArray(), scale: o.scale.x };
});
