// How the future self looks, as plain data. CONTRACTS.md "Look tiers": the server sends wealth_tier and health_tier
// (1 to 4, or null) with the facts message; null keeps the middle look. No three.js here, so it runs under node --test.
// DESIGN-RULES.md: the palette is Ink, Paper, Dusk grey and one amber accent, nothing else. Every colour below is a
// tint or shade mixed from those four, and the only amber is the single accent (the chain, top tier).

export const PALETTE = { ink: "#15130f", paper: "#f3eee4", dusk: "#8a8378", amber: "#c8893a" };

const hex = (h) => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16));
// t = 0 gives a, t = 1 gives b.
export function mix(a, b, t) {
  const A = hex(a), B = hex(b);
  return "#" + A.map((v, i) => Math.round(v + (B[i] - v) * t).toString(16).padStart(2, "0")).join("");
}

export const MIDDLE_TIER = 2;
// A tier from the server, or the middle look when it is missing or not 1 to 4.
export const tierOf = (v) => (Number.isInteger(v) && v >= 1 && v <= 4 ? v : MIDDLE_TIER);

const { ink, paper, dusk, amber } = PALETTE;

// One look per wealth tier. Names are for the team; the person never sees them (CONTRACTS.md).
export const LOOKS = {
  1: { name: "Modest", outfit: "knit", body: mix(dusk, ink, 0.3), trim: mix(dusk, ink, 0.15), shirt: null, chain: false },
  2: { name: "Comfortable", outfit: "cardigan", body: mix(dusk, ink, 0.5), trim: mix(dusk, ink, 0.35), shirt: mix(paper, dusk, 0.3), chain: false },
  3: { name: "Established", outfit: "blazer", body: mix(ink, dusk, 0.3), trim: mix(ink, dusk, 0.5), shirt: mix(paper, dusk, 0.18), chain: false, watch: mix(paper, dusk, 0.45) },
  4: { name: "Affluent", outfit: "tailored", body: mix(ink, dusk, 0.12), trim: mix(ink, dusk, 0.32), shirt: mix(paper, dusk, 0.12), chain: true, accent: amber, watch: mix(paper, dusk, 0.35) },
};

// Posture by health tier: how far the shoulders drop (metres), how narrow they sit (scale), how far the chest leans
// forward (radians). Tier 3 and 4 are upright. Kept gentle: warm, never a caricature of frailty.
export const POSTURE = {
  1: { drop: 0.03, width: 0.92, lean: 0.14 },
  2: { drop: 0.015, width: 0.96, lean: 0.07 },
  3: { drop: 0, width: 1, lean: 0 },
  4: { drop: -0.006, width: 1.03, lean: -0.03 },
};

export const lookFor = (wealth) => LOOKS[tierOf(wealth)];
export const postureFor = (health) => POSTURE[tierOf(health)];

// Move `value` toward `target` over about `seconds` (DESIGN-RULES: 300 to 500 ms, nothing bounces).
export function approach(value, target, dt, seconds = 0.4) {
  const step = dt / seconds;
  return value < target ? Math.min(target, value + step) : Math.max(target, value - step);
}

// The future self's upper body, outfit and backdrop (CONTRACTS.md "Look tiers"). Four wealth looks and four posture
// levels, driven by the wealth_tier and health_tier on the server's facts message. They blend over about 0.4 s when a
// slider moves (DESIGN-RULES: slow, smooth, nothing bounces). Works on any saved head with no rebuild: the head file
// stops at the neck, so the shoulders and clothes are drawn here, in the mirror's space (face centre at the origin,
// chin about 0.14 m down, facing +z).
import * as THREE from "three";
import { LOOKS, postureFor, tierOf, approach } from "./looks-data.js";
import { paintBackdrop, BACKDROP_SIZE } from "./backdrops.js";

const NECK_BASE_Y = -0.19; // where the shoulders start under the chin
const BLEND_SECONDS = 0.4;

const mat = (color, extra = {}) => new THREE.MeshStandardMaterial({ color, roughness: 0.9, metalness: 0, flatShading: false, transparent: true, opacity: 0, ...extra });

// Shoulders to waist, symmetric, origin at the base of the neck (x across, y up).
function torsoShape(half = 0.262, drop = 0.31) {
  const s = new THREE.Shape();
  s.moveTo(-0.056, 0.02);
  s.quadraticCurveTo(-0.12, 0.0, -0.2, -0.03);
  s.quadraticCurveTo(-half, -0.055, -half - 0.005, -0.12);
  s.lineTo(-half, -drop);
  s.lineTo(half, -drop);
  s.lineTo(half + 0.005, -0.12);
  s.quadraticCurveTo(half, -0.055, 0.2, -0.03);
  s.quadraticCurveTo(0.12, 0.0, 0.056, 0.02);
  s.closePath();
  return s;
}
const extrude = (shape, depth, bevel = 0.008) => {
  const g = new THREE.ExtrudeGeometry(shape, { depth, bevelEnabled: true, bevelThickness: bevel, bevelSize: bevel, bevelSegments: 2, curveSegments: 14 });
  g.translate(0, 0, -depth / 2);
  return g;
};
const tri = (pts) => { const s = new THREE.Shape(); pts.forEach(([x, y], i) => (i ? s.lineTo(x, y) : s.moveTo(x, y))); s.closePath(); return s; };
const mirrorPts = (pts) => pts.map(([x, y]) => [-x, y]);

// One outfit: a group of meshes at the torso's local origin.
function buildOutfit(look, skin) {
  const g = new THREE.Group();
  const add = (geo, color, pos = [0, 0, 0], extra) => { const m = new THREE.Mesh(geo, mat(color, extra)); m.position.set(...pos); g.add(m); return m; };
  const front = 0.062; // z of the chest's front face
  add(extrude(torsoShape(), 0.11), look.body);

  // Arms hanging at the sides: a sleeve, a cuff, a bare wrist and hand in the face's skin tone. Out of sight in the
  // laptop view (it stops at the chest) but in the headset the whole person is there.
  for (const side of [-1, 1]) {
    const arm = new THREE.Group();
    arm.position.set(side * 0.272, -0.07, 0);
    arm.rotation.z = side * 0.05;
    const sleeve = new THREE.Mesh(new THREE.CapsuleGeometry(0.047, 0.3, 6, 14), mat(look.body));
    sleeve.position.y = -0.17;
    arm.add(sleeve);
    const cuff = new THREE.Mesh(new THREE.CylinderGeometry(0.044, 0.044, 0.026, 16), mat(look.trim));
    cuff.position.y = -0.345;
    arm.add(cuff);
    const hand = new THREE.Mesh(new THREE.CapsuleGeometry(0.03, 0.07, 4, 10), skin);
    hand.position.y = -0.42;
    arm.add(hand);
    if (look.watch && side === -1) {
      const w = new THREE.Mesh(new THREE.TorusGeometry(0.032, 0.006, 8, 22), mat(look.watch, { roughness: 0.3, metalness: 0.8 }));
      w.rotation.x = Math.PI / 2;
      w.position.y = -0.375;
      arm.add(w);
    }
    g.add(arm);
  }

  if (look.outfit === "knit") {
    // Rolled collar and a ribbed hem.
    const ring = add(new THREE.TorusGeometry(0.062, 0.016, 10, 28), look.trim, [0, 0.008, 0.004]);
    ring.rotation.x = Math.PI / 2;
    add(new THREE.BoxGeometry(0.53, 0.026, 0.118), look.trim, [0, -0.298, 0]);
  } else if (look.outfit === "cardigan") {
    add(extrude(tri([[-0.075, 0.012], [0.075, 0.012], [0, -0.15]]), 0.004, 0.002), look.shirt, [0, 0, front]); // shirt in the V
    const c1 = add(new THREE.BoxGeometry(0.05, 0.034, 0.02), look.shirt, [-0.07, 0.006, 0.054]); c1.rotation.z = -0.5; // collar points
    const c2 = add(new THREE.BoxGeometry(0.05, 0.034, 0.02), look.shirt, [0.07, 0.006, 0.054]); c2.rotation.z = 0.5;
    add(new THREE.BoxGeometry(0.014, 0.29, 0.012), look.trim, [-0.078, -0.165, front + 0.002]); // cardigan edge, buttoned
    add(new THREE.BoxGeometry(0.014, 0.29, 0.012), look.trim, [0.078, -0.165, front + 0.002]);
  } else {
    // Blazer or tailored jacket: shirt in the V, wide lapels, a folded pocket square.
    add(extrude(tri([[-0.062, 0.014], [0.062, 0.014], [0, -0.16]]), 0.004, 0.002), look.shirt, [0, 0, front]);
    const lapel = [[-0.06, 0.02], [-0.13, -0.05], [-0.06, -0.19], [-0.012, -0.15]];
    add(extrude(tri(lapel), 0.012, 0.003), look.trim, [0, 0, front + 0.006]);
    add(extrude(tri(mirrorPts(lapel)), 0.012, 0.003), look.trim, [0, 0, front + 0.006]);
    add(new THREE.BoxGeometry(0.036, 0.02, 0.01), look.shirt, [-0.15, -0.12, front + 0.004]);
    if (look.chain) {
      // The one accent: a fine amber chain with a small pendant, lying on the shirt.
      const arc = new THREE.TorusGeometry(0.084, 0.0034, 8, 48, Math.PI);
      const chain = add(arc, look.accent, [0, 0.018, front + 0.012], { roughness: 0.25, metalness: 0.9 });
      chain.rotation.z = Math.PI;
      chain.scale.y = 1.5;
      add(new THREE.SphereGeometry(0.0095, 14, 10), look.accent, [0, -0.108, front + 0.014], { roughness: 0.25, metalness: 0.9 });
    }
  }
  return g;
}

export function createLooks() {
  const group = new THREE.Group();
  group.name = "looks";

  // Backdrops: one plane per tier behind the head, cross-faded.
  const backdrops = {};
  const bg = new THREE.Group();
  group.add(bg);
  for (const tier of [1, 2, 3, 4]) {
    let texture = null;
    if (typeof document !== "undefined") {
      const canvas = document.createElement("canvas");
      canvas.width = BACKDROP_SIZE.w;
      canvas.height = BACKDROP_SIZE.h;
      paintBackdrop(canvas.getContext("2d"), tier);
      texture = new THREE.CanvasTexture(canvas);
      texture.colorSpace = THREE.SRGBColorSpace;
    }
    const m = new THREE.MeshBasicMaterial({ map: texture, transparent: true, opacity: 0, depthWrite: false });
    const plane = new THREE.Mesh(new THREE.PlaneGeometry(1.3, 0.98), m);
    plane.position.set(0, -0.1, -0.3);
    plane.renderOrder = -2;
    plane.visible = false;
    bg.add(plane);
    backdrops[tier] = { plane, mat: m, alpha: 0 };
  }

  // Outfits on a body group so posture can move them together.
  const body = new THREE.Group();
  body.position.set(0, NECK_BASE_Y, -0.02);
  group.add(body);
  // A short neck in the person's skin tone: the head file's own neck fades out, which would leave a gap above the collar.
  const neckMat = new THREE.MeshStandardMaterial({ color: new THREE.Color(0.5, 0.36, 0.3), roughness: 0.8, metalness: 0 });
  const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.058, 0.13, 28), neckMat);
  neck.position.set(0, -0.125, -0.035);
  group.add(neck);
  const outfits = {};
  for (const tier of [1, 2, 3, 4]) {
    const o = buildOutfit(LOOKS[tier], neckMat);
    o.visible = false;
    body.add(o);
    outfits[tier] = { group: o, alpha: 0 };
  }

  // A walking cane leaning against the right side when health is in the lowest tier (CONTRACTS.md: a cane or armrest nearby).
  const caneMat = mat("#4a443b", { roughness: 0.6 });
  const cane = new THREE.Group();
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.0085, 0.0075, 0.62, 12), caneMat);
  shaft.position.y = -0.3;
  const crook = new THREE.Mesh(new THREE.TorusGeometry(0.036, 0.0095, 8, 20, Math.PI), caneMat);
  crook.position.set(-0.036, 0.0, 0);
  cane.add(shaft, crook);
  cane.position.set(0.37, -0.13, 0.06);
  cane.rotation.z = -0.05;
  cane.visible = false;
  group.add(cane);
  let caneAlpha = 0;

  const state = { wealth: 2, health: 3 }; // targets; start in the middle until the server says otherwise
  const posture = { drop: 0, width: 1, lean: 0 };
  const targetPosture = () => postureFor(state.health);
  const setOpacity = (o, a) => o.group.traverse((m) => { if (m.isMesh) m.material.opacity = a; });

  // Show a look immediately with no blending (first frame, tests).
  function snap() {
    caneAlpha = state.health === 1 ? 1 : 0;
    for (const t of [1, 2, 3, 4]) {
      const on = t === state.wealth ? 1 : 0;
      outfits[t].alpha = on;
      backdrops[t].alpha = on;
    }
    Object.assign(posture, targetPosture());
    apply();
  }

  function apply() {
    cane.visible = caneAlpha > 0.01;
    caneMat.opacity = caneAlpha;
    for (const t of [1, 2, 3, 4]) {
      const o = outfits[t], b = backdrops[t];
      o.group.visible = o.alpha > 0.01;
      setOpacity(o, o.alpha);
      b.plane.visible = b.alpha > 0.01;
      b.mat.opacity = b.alpha;
    }
    body.position.y = NECK_BASE_Y - posture.drop;
    body.scale.x = posture.width;
    body.rotation.x = posture.lean;
  }

  snap();
  return {
    group,
    // Both arguments are the server's 1 to 4 (or null: keep the middle look).
    setTiers(wealth, health) {
      state.wealth = tierOf(wealth);
      state.health = tierOf(health);
    },
    get tiers() { return { ...state }; },
    // Linear-colour skin tone from the head (head.skinTone); keeps the neck the same shade as the face.
    setSkin(color) {
      if (color) neckMat.color.copy(color);
    },
    snap,
    update(dt) {
      for (const t of [1, 2, 3, 4]) {
        const on = t === state.wealth ? 1 : 0;
        outfits[t].alpha = approach(outfits[t].alpha, on, dt, BLEND_SECONDS);
        backdrops[t].alpha = approach(backdrops[t].alpha, on, dt, BLEND_SECONDS * 1.5);
      }
      caneAlpha = approach(caneAlpha, state.health === 1 ? 1 : 0, dt, BLEND_SECONDS);
      const target = targetPosture();
      const k = 1 - Math.exp(-dt * 6); // exponential ease, settles in about 0.5 s
      for (const key of ["drop", "width", "lean"]) posture[key] += (target[key] - posture[key]) * k;
      apply();
    },
  };
}

// Four backdrops painted onto a canvas, one per wealth tier (CONTRACTS.md "Look tiers"): a small tidy room, a cosy living
// room, a bright home with a garden view, a grand estate. Flat shapes in tints of the four design colours, no gradients
// beyond a soft sky, no shadows. No three.js, so the painting runs under node --test with a fake context.
import { PALETTE, mix } from "./looks-data.js";

const { ink, paper, dusk } = PALETTE;
const W = 1024;
const H = 768;
export const BACKDROP_SIZE = { w: W, h: H };

const rect = (ctx, color, x, y, w, h) => { ctx.fillStyle = color; ctx.fillRect(x, y, w, h); };
const circle = (ctx, color, x, y, r) => { ctx.fillStyle = color; ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2); ctx.fill(); };
const poly = (ctx, color, pts) => { ctx.fillStyle = color; ctx.beginPath(); pts.forEach(([x, y], i) => (i ? ctx.lineTo(x, y) : ctx.moveTo(x, y))); ctx.closePath(); ctx.fill(); };

function window4(ctx, x, y, w, h, frame, glass) {
  rect(ctx, frame, x - 10, y - 10, w + 20, h + 20);
  rect(ctx, glass, x, y, w, h);
  rect(ctx, frame, x + w / 2 - 4, y, 8, h);
  rect(ctx, frame, x, y + h / 2 - 4, w, 8);
}

const SCENES = {
  // 1 Modest: a small, tidy, lived-in room.
  1(ctx) {
    rect(ctx, mix(paper, dusk, 0.3), 0, 0, W, H);
    rect(ctx, mix(dusk, ink, 0.2), 0, 600, W, 168); // floor
    rect(ctx, mix(paper, dusk, 0.55), 0, 590, W, 14); // skirting
    window4(ctx, 110, 150, 230, 280, mix(paper, dusk, 0.6), mix(paper, dusk, 0.1));
    rect(ctx, mix(dusk, ink, 0.1), 70, 130, 40, 330); // curtain
    rect(ctx, mix(paper, dusk, 0.55), 700, 150, 190, 230); // picture frame
    rect(ctx, mix(paper, dusk, 0.15), 716, 166, 158, 198);
    poly(ctx, mix(dusk, ink, 0.35), [[716, 364], [780, 270], [820, 320], [850, 285], [874, 364]]);
    rect(ctx, mix(dusk, ink, 0.3), 560, 500, 60, 100); // pot
    for (const [x, y, r] of [[590, 470, 38], [555, 495, 30], [625, 495, 30], [590, 430, 26]]) circle(ctx, mix(dusk, ink, 0.45), x, y, r);
  },
  // 2 Comfortable: a cosy living room with a window.
  2(ctx) {
    rect(ctx, mix(paper, dusk, 0.35), 0, 0, W, H);
    rect(ctx, mix(dusk, ink, 0.3), 0, 610, W, 158);
    rect(ctx, mix(paper, dusk, 0.6), 0, 600, W, 14);
    window4(ctx, 560, 120, 330, 300, mix(paper, dusk, 0.65), mix(paper, dusk, 0.05));
    rect(ctx, mix(paper, dusk, 0.5), 540, 430, 370, 16); // sill
    rect(ctx, mix(dusk, ink, 0.5), 70, 90, 250, 510); // bookshelf
    for (let r = 0; r < 4; r++) {
      rect(ctx, mix(dusk, ink, 0.65), 80, 190 + r * 105, 230, 8);
      for (let i = 0; i < 9; i++) rect(ctx, mix(paper, dusk, 0.25 + ((i * 7 + r * 3) % 5) * 0.12), 90 + i * 24, 120 + r * 105 + ((i * 5) % 3) * 8, 18, 68 - ((i * 5) % 3) * 8);
    }
    rect(ctx, mix(dusk, ink, 0.4), 380, 520, 560, 90); // sofa back
    rect(ctx, mix(dusk, ink, 0.28), 380, 570, 560, 40);
    rect(ctx, mix(dusk, ink, 0.4), 700, 470, 6, 130); // floor lamp
    poly(ctx, mix(paper, dusk, 0.2), [[670, 470], [740, 470], [725, 420], [685, 420]]);
  },
  // 3 Established: a bright open home, garden through a wide window.
  3(ctx) {
    rect(ctx, mix(paper, dusk, 0.15), 0, 0, W, H);
    rect(ctx, mix(paper, dusk, 0.45), 0, 640, W, 128); // light floor
    const gx = 90, gy = 70, gw = 844, gh = 540;
    rect(ctx, mix(paper, dusk, 0.05), gx, gy, gw, gh); // sky
    rect(ctx, mix(paper, dusk, 0.3), gx, gy + 300, gw, gh - 300); // lawn
    poly(ctx, mix(dusk, ink, 0.1), [[gx, gy + 300], [gx + 200, gy + 230], [gx + 420, gy + 290], [gx + 620, gy + 220], [gx + gw, gy + 280], [gx + gw, gy + 320], [gx, gy + 320]]); // hills
    for (const [x, y, r] of [[250, 330, 60], [330, 350, 44], [760, 320, 70], [690, 360, 46]]) { rect(ctx, mix(dusk, ink, 0.55), x - 5, y, 10, 110); circle(ctx, mix(dusk, ink, 0.4), x, y, r); }
    for (let i = 1; i < 4; i++) rect(ctx, mix(ink, dusk, 0.4), gx + (gw * i) / 4 - 5, gy, 10, gh); // mullions
    rect(ctx, mix(ink, dusk, 0.4), gx - 10, gy - 10, gw + 20, 12);
    rect(ctx, mix(ink, dusk, 0.4), gx - 10, gy + gh - 2, gw + 20, 12);
  },
  // 4 Affluent: a grand house in the distance, framed by tall drapes.
  4(ctx) {
    const sky = ctx.createLinearGradient ? ctx.createLinearGradient(0, 0, 0, 520) : null;
    if (sky) { sky.addColorStop(0, mix(paper, dusk, 0.3)); sky.addColorStop(1, mix(paper, dusk, 0.05)); }
    ctx.fillStyle = sky || mix(paper, dusk, 0.15);
    ctx.fillRect(0, 0, W, 520);
    rect(ctx, mix(paper, dusk, 0.3), 0, 520, W, 248); // lawn
    poly(ctx, mix(paper, dusk, 0.12), [[470, 768], [554, 768], [532, 540], [492, 540]]); // drive
    const house = mix(dusk, ink, 0.3), light = mix(paper, dusk, 0.35);
    rect(ctx, house, 250, 330, 524, 210); // main block
    rect(ctx, house, 150, 380, 110, 160); // wings
    rect(ctx, house, 764, 380, 110, 160);
    poly(ctx, mix(dusk, ink, 0.45), [[400, 330], [624, 330], [512, 250]]); // pediment
    for (let i = 0; i < 5; i++) rect(ctx, light, 420 + i * 46, 340, 14, 200); // columns
    for (let r = 0; r < 2; r++) for (let i = 0; i < 3; i++) { rect(ctx, light, 280 + i * 42, 360 + r * 80, 26, 50); rect(ctx, light, 686 + i * 42 - 0, 360 + r * 80, 26, 50); }
    for (const x of [175, 220, 790, 835]) rect(ctx, mix(paper, dusk, 0.5), x, 420, 22, 40);
    rect(ctx, mix(paper, dusk, 0.5), 440, 540, 144, 14); // steps
    for (const x of [120, 904]) { rect(ctx, mix(dusk, ink, 0.55), x - 5, 470, 10, 70); circle(ctx, mix(dusk, ink, 0.4), x, 450, 46); }
    for (const x of [380, 644]) circle(ctx, mix(dusk, ink, 0.45), x, 570, 28); // topiary
    rect(ctx, mix(ink, dusk, 0.12), 0, 0, 90, H); // drapes
    rect(ctx, mix(ink, dusk, 0.12), W - 90, 0, 90, H);
    rect(ctx, mix(ink, dusk, 0.28), 90, 0, 10, H);
    rect(ctx, mix(ink, dusk, 0.28), W - 100, 0, 10, H);
  },
};

// Paint one tier's backdrop, with a soft dark edge so it reads as a picture rather than a hard rectangle.
export function paintBackdrop(ctx, tier) {
  ctx.clearRect(0, 0, W, H);
  (SCENES[tier] ?? SCENES[2])(ctx);
  if (ctx.createRadialGradient) {
    const g = ctx.createRadialGradient(W / 2, H / 2, H * 0.45, W / 2, H / 2, H * 0.95);
    g.addColorStop(0, "rgba(21,19,15,0)");
    g.addColorStop(1, "rgba(21,19,15,0.55)");
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, W, H);
  }
  return true;
}

