import { weld, simplify, textureCompress, prune, dedup, flatten, join } from "@gltf-transform/functions";
import { MeshoptSimplifier } from "meshoptimizer";
import sharp from "sharp";
const [,, inp, out, target] = process.argv;
const io = new NodeIO().registerExtensions(ALL_EXTENSIONS);
const doc = await io.read(inp);
let tris = 0; for (const m of doc.getRoot().listMeshes()) for (const p of m.listPrimitives()) tris += (p.getIndices()?.getCount() ?? 0) / 3;
const skinned = doc.getRoot().listSkins().length > 0;
await doc.transform(prune(), dedup(), weld());
if (!skinned && tris > +target) {
  await MeshoptSimplifier.ready;
  await doc.transform(simplify({ simplifier: MeshoptSimplifier, ratio: +target / tris, error: 0.01, lockBorder: false }));
}
await doc.transform(textureCompress({ encoder: sharp, resize: [1024, 1024] }), prune());
let after = 0; for (const m of doc.getRoot().listMeshes()) for (const p of m.listPrimitives()) after += (p.getIndices()?.getCount() ?? 0) / 3;
await io.write(out, doc);
console.log(inp.split("/").pop(), "tris", Math.round(tris), "->", Math.round(after));
EOF
